`timescale 1ns/1ps
// snn2_d: hardwired, fully parallel SNN core generated by sw/gen_rtl.py from d_s1 (do not edit; regenerate).
// 140 inputs (spike counts per frame, 5-bit saturating) -> 64 -> 64 -> 20 classes; synaptic delays 0..29 frames, memoryless neurons.
// Ternary weights as wiring (W1 5168, W2 7825, W3 1034 synapses); thresholds T1 = 4, T2 = 2;
// 60 frames per sample; read-out: maximum over the frames per class, then argmax.
module snn2_d (
  input  wire        clk,
  input  wire        reset,          // synchronous, active high
  input  wire        ev_valid,       // input event: channel ev_ch, at most one per cycle
  input  wire [7:0]  ev_ch,
  output wire        ev_ready,
  input  wire        tick,           // end of a frame
  input  wire        tick_last,      // with tick: last frame of the sample
  output wire        tick_ready,
  output reg         out_valid,      // class of the sample (one-cycle pulse)
  output reg  [4:0]  out_class,
  output wire        score_valid,    // the 20 class scores, one per cycle, before out_valid
  output wire [6:0] score,
  output wire        busy,
  output wire        core_clk_en     // the core clock runs (for the measurement: activity gate of the testbench)
);
  localparam [2:0] S_IDLE = 3'd0, S_L1 = 3'd1, S_S1 = 3'd2, S_L2 = 3'd3, S_L3 = 3'd4, S_ARG = 3'd5, S_CLR = 3'd6;
  reg  [2:0] state;                  // IDLE: count events; L1: 5 bit planes; S1: load s1 (shift the lines); L2: load s2;
                                     // L3: update the read-out; ARG: argmax (last frame); CLR: output the class, clear
  reg  [2:0] bidx;                   // layer-1 bit plane (4 .. 0)
  reg        last;                   // the frame being processed is the last of the sample
  reg  [4:0] k;                      // argmax scan index

  // ---------------------------------------------------------------- always-on domain: wake-up register and root clock gate
  reg  en_q;
  wire en_d = reset | ev_valid | tick | (state != S_IDLE) | out_valid;
  always @(posedge clk) en_q <= en_d;
  assign core_clk_en = en_q;
  wire core_clk;
  sky130_fd_sc_hd__dlclkp_4 u_icg (.CLK(clk), .GATE(en_q), .GCLK(core_clk));

  // handshake: events are accepted while idle and awake; a frame tick when no event is pending
  wire idle = (state == S_IDLE);
  assign ev_ready   = idle & en_q;
  assign tick_ready = idle & en_q & ~ev_valid;
  assign busy       = ~idle;
  // Inside the core the acceptance needs no en_q: everything it drives is clocked through the root clock gate, i.e. only in cycles
  // with en_q = 1. (en_q is launched by the always-on clock, up to ~2 ns before the clocks behind two more gates: these paths would
  // need hold buffers.)
  wire ev_acc   = ev_valid & idle;
  wire tick_acc = tick & idle & ~ev_valid;

  // control clock: the state machine, the argmax registers and the register-bank clock gates, clocked only while a frame is
  // processed (not in the event-counting cycles)
  wire ctl_clk;
  sky130_fd_sc_hd__dlclkp_4 u_icg_ctl (.CLK(core_clk), .GATE(reset | tick_acc | ~idle | out_valid), .GCLK(ctl_clk));
  wire st_l1 = (state == S_L1), st_s1 = (state == S_S1), st_l2 = (state == S_L2), st_l3 = (state == S_L3), st_clr = (state == S_CLR);

  // Control of the datapath registers (data side), launched on the falling edge of the control clock, i.e. half a cycle before
  // the rising edge that uses it: these signals reach thousands of registers behind deeper clock gates (later clock edges), which
  // would otherwise need hold buffers. The clock-gate enables (GATE pins) use the rising-edge state directly.
  reg  st_l1_n, st_s1_n, st_clr_n, first_plane_n;
  reg  [2:0] bidx_n;
  always @(negedge ctl_clk) begin
    st_l1_n <= st_l1; st_s1_n <= st_s1; st_clr_n <= st_clr; bidx_n <= bidx; first_plane_n <= (bidx == 3'd4);
  end
  wire clr_cnt  = reset | st_s1_n;   // counters: cleared when s1 is loaded (end of the frame)
  wire clr_bank = reset | st_clr_n;  // s1, delay lines, membranes, s2, read-out: cleared at the end of the sample

  // ---------------------------------------------------------------- 140 input counters (5-bit, saturating)
  // 9 group clock gates (16 counters each, selected by ev_ch[7:4]) feed one clock gate per counter (selected by ev_ch[3:0]):
  // an event clocks one group gate and one counter. In the layer-1 cycles a counter drives one bit (plane bidx) into the trees,
  // 0 otherwise (operand isolation: counting events does not toggle the trees).
